{
  "name": "Bronkhorst EL-FLOW 气体质量流量控制器",
  "name_en": "Bronkhorst EL-FLOW gas mass flow controller",
  "manufacturer": "Bronkhorst",
  "description": "一种带控制阀的气体质量流量控制器，用于测量并精密调节实验或工艺气体流量。它常用于气体输送、混气、反应供气以及其他需要稳定流量设定的实验室和过程控制场景。",
  "description_en": "A gas mass flow controller with an integrated control valve, used to measure and precisely regulate gas flow in laboratory or process systems. It is commonly used for gas delivery, gas mixing, reactor feed control, and other applications requiring stable flow setpoints.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化流量控制器并使其进入可操作状态。",
      "description_en": "Initialize the flow controller and prepare it for operation."
    },
    {
      "action_name": "auto-write",
      "description": "向流量控制器发送底层命令。",
      "description_en": "Send a low-level command to the flow controller."
    },
    {
      "action_name": "auto-read",
      "description": "读取流量控制器返回的数据。",
      "description_en": "Read the response data from the flow controller."
    },
    {
      "action_name": "auto-get_valve_output",
      "description": "获取阀门输出。",
      "description_en": "Get the valve output."
    },
    {
      "action_name": "auto-set_setpoint",
      "description": "设置流量设定值。",
      "description_en": "Set the flow setpoint."
    },
    {
      "action_name": "auto-get_setpoint",
      "description": "获取流量设定值。",
      "description_en": "Get the flow setpoint."
    },
    {
      "action_name": "auto-set_mode",
      "description": "设置工作模式。",
      "description_en": "Set the operating mode."
    },
    {
      "action_name": "auto-get_mode",
      "description": "获取工作模式。",
      "description_en": "Get the operating mode."
    },
    {
      "action_name": "auto-get_flow",
      "description": "获取当前流量。",
      "description_en": "Get the current flow rate."
    }
  ],
  "tag_hints": [
    "mass flow control",
    "gas flow regulation",
    "thermal mass flow controller",
    "process gas delivery",
    "gas mixing",
    "RS-232 communication"
  ]
}

